def is_valid_tag_sequence(s):
    import re
    pattern = re.compile(r'(</?)([a-z]+)>')
    pos = 0
    stack = []
    while pos < len(s):
        m = pattern.match(s, pos)
        if not m:
            return False
        bracket, word = m.group(1), m.group(2)
        if bracket == '<':
            stack.append(word)
        else:
            if not stack or stack[-1] != word:
                return False
            stack.pop()
        pos = m.end()
    return not stack

